sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float amount;
uniform float radius;

half4 main(float2 coord) {
    float2 c = center * size;
    float2 d = coord - c;
    float r = max(radius * min(size.x, size.y), 0.0001);
    float a = clamp(amount, -1.0, 1.0);
    float len = length(d);
    if (a < 0.0 && len < r) {
        float u = len / r;
        return image.eval(c + d / max(len, 0.0001) * (r * pow(u, 1.0 + 0.77 * a * (1.0 - u))));
    }
    float t = clamp(1.0 - len / r, 0.0, 1.0);
    float k = max(1.0 - a * t * t, 0.0);
    k *= k;
    return image.eval(c + d * k * k);
}
